select *, percent_rank() over (partition by device_code order by status_bits desc) as status_bits_percent_rank, row_number() over (partition by device_code order by temp_c desc, id) as seq_no, ntile(10) over w_ordered as humidity_bucket, sum(status_bits) over (order by reading_ts, id rows between unbounded preceding and current row) as running_status_bits, round(pressure / sum(pressure) over (partition by device_code), 4) as pressure_share from device_readings window w_ordered as (partition by device_code order by humidity desc, id)
